BATCH_SIZE = 2
MAX_ATTEMPTS = 3


def deliver(records, send):
    for start in range(0, len(records), BATCH_SIZE):
        batch = records[start:start + BATCH_SIZE]
        for attempt in range(MAX_ATTEMPTS):
            try:
                send(batch)
                break
            except TimeoutError:
                if attempt == MAX_ATTEMPTS - 1:
                    raise
    return len(records)
